use moloch_replay::{amount,money,engine::Engine,session::Session};
use serde_json::{Value,json};use sha2::{Digest,Sha256};use std::{fs,path::PathBuf};
const T:&str="11111111-1111-4111-8111-111111111111";const P:&str="22222222-2222-4222-8222-222222222222";
fn iso(n:i64)->String{chrono::DateTime::from_timestamp_millis(1_792_054_800_000+n).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash(v:&Value)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
fn receipt(path:String,data:Value,n:i64)->Value{json!({"endpoint":path,"requestStartedAt":iso(n),"receivedAt":iso(n+1),"status":200,"data":data})}
fn digest(v:&Value)->String{#[derive(serde::Serialize)]#[serde(rename_all="camelCase")]struct R<'a>{endpoint:&'a Value,request_started_at:&'a Value,received_at:&'a Value,status:&'a Value,data:&'a Value}format!("{:x}",Sha256::digest(serde_json::to_vec(&R{endpoint:&v["endpoint"],request_started_at:&v["requestStartedAt"],received_at:&v["receivedAt"],status:&v["status"],data:&v["data"]}).unwrap()))}
struct F{root:PathBuf,bank:Option<Session>,policy:Value,seed:Value}
impl Drop for F{fn drop(&mut self){self.bank.take();let _=fs::remove_dir_all(&self.root);}}
impl F{
 fn new(adopt:bool)->Self{let root=std::env::temp_dir().join(format!("owner-capital-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir(&root).unwrap();let policy=json!({"initialCash":"40000.000000","maximumCommitted":"40000.000000","maximumMarketCost":"10000.000000","quantity":2,"feePerShare":"0.010000","entryDepthBps":10000,"maximumMarkets":3,"entryStopAt":iso(3_600_000)});let seed=json!({"runId":"capital-fixture","tournamentId":T,"availableCash":"70850.430000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});let bank=Session::open_live(&root.join("bank"),&policy,&seed).unwrap();let mut f=Self{root,bank:Some(bank),policy,seed};if adopt{let mut rows=vec![];for(ex,n)in [("101",10000),("102",10000),("103",7477)]{let mut lots=vec![json!({"lotId":format!("9{ex}"),"quantity":n,"side":"YES","entryPrice":"0.900000","openedAt":iso(-1000)})];let mut quantity=n;if ex=="103"{lots.push(json!({"lotId":"9999","quantity":37,"side":"YES","entryPrice":"0.005000","openedAt":iso(-1000)}));quantity+=37;}let principal=if ex=="103"{"6729.485000"}else{"9000.000000"};rows.push(json!({"exchangeId":ex,"marketId":ex,"quantity":quantity,"lotPrincipal":principal,"reportedCostBasis":principal,"reportedMinusLotPrincipal":"0.000000","basisClassification":"exact","lots":lots}));}f.put(&json!({"type":"actual_position_adoption","source":"official_sig_api_v1","authority":"human_moloch_inherited_management_20261015","complete":true,"receiptHash":"d".repeat(64),"tournamentId":T,"receivedAt":iso(0),"processedAt":iso(0),"requestStartedAt":iso(0),"openingCost":"24729.485000","effectiveMaximumMarkets":6,"positions":rows})).unwrap();}f}
 fn b(&self)->&Session{self.bank.as_ref().unwrap()}
 fn put(&mut self,e:&Value)->Result<bool,Box<dyn std::error::Error>>{let n=self.b().last_source_sequence("fixture")+1;self.bank.as_mut().unwrap().accept("fixture",n,e)}
 fn event(&self,delta:&str,at:i64)->Value{let b=self.b();let wallet=&b.engine().wallet;let official=amount(self.seed["availableCash"].as_str().unwrap()).unwrap()+wallet.cash-wallet.initial+b.engine().opening_inventory_cost();let positions:Vec<_>=["101","102","103","104"].iter().filter_map(|ex|{let n=wallet.quantity(ex,moloch_replay::Side::Yes)as i64-wallet.quantity(ex,moloch_replay::Side::No)as i64;if n==0{None}else{Some(json!({"exchangeId":ex,"marketId":ex,"quantity":n,"lots":[]}))}}).collect();let receipts=json!({"account":receipt(format!("/account?tournamentId={T}"),json!({"id":P,"balance":money(official),"availableAdvance":0,"buyingPower":money(official)}),at-8),"collateral":receipt(format!("/portfolio/collateral?tournamentId={T}"),json!({"availableAdvance":0,"data":[{"profileId":P,"tournamentId":T,"componentId":"original","outstandingAdvance":0}]}),at-6),"positions":receipt("/tournaments/cup/portfolio/positions".into(),json!({"positions":positions}),at-4),"orders":receipt(format!("/orders?status=open&limit=200&tournamentId={T}"),json!({"data":[],"coverage":{"complete":true},"pagination":{"hasMore":false,"nextCursor":null}}),at-2)});let evidence:Vec<_>=["account","collateral","positions","orders"].iter().map(|k|json!({"receiptSha256":digest(&receipts[*k]),"retainedBytesSha256":"b".repeat(64)})).collect();let delta=amount(delta).unwrap();json!({"type":"live_capital_allocation_v1","source":"moloch_live_dispatcher","authorizationId":"human_moloch_additional_cash_20261016","allocationId":format!("capital-{}",b.last_source_sequence("fixture")),"controlSha256":"b".repeat(64),"mandateSha256":"c".repeat(64),"receivedAt":iso(at),"processedAt":iso(at),"bankScope":{"runId":"capital-fixture","bankManifestHash":b.manifest_hash(),"tournamentId":T,"tournamentSlug":"cup","profileId":P},"expectedReportHash":hash(&b.engine().report().unwrap()),"expectedPolicySha256":hash(b.engine().policy()),"expectedPreviousAllocationSha256":b.engine().owner_capital_allocation_record().map_or(Value::Null,|r|r["sha256"].clone()),"expectedInitialCash":money(wallet.initial),"expectedMaximumCommitted":b.engine().policy()["maximumCommitted"],"delta":money(delta),"effectiveInitialCash":money(wallet.initial+delta),"effectiveMaximumCommitted":money(amount(b.engine().policy()["maximumCommitted"].as_str().unwrap()).unwrap()+delta),"scopeExchanges":{"101":"101","102":"102","103":"103","104":"104"},"boundary":{"nativeHead":b.durable_head(),"ordinaryDispatchHash":"b".repeat(64),"packageDispatchHash":"b".repeat(64),"queueHeadHash":"b".repeat(64),"ownerLeaseHash":"b".repeat(64),"unknownCount":0,"activeRequest":null,"unsubmittedOrderIds":b.engine().order_records().iter().filter(|q|q["retired"]==false).map(|q|q["id"].clone()).collect::<Vec<_>>()},"receipts":receipts,"originalSourceEvidence":evidence})}
 fn resign(e:&mut Value){for(i,k)in ["account","collateral","positions","orders"].iter().enumerate(){e["originalSourceEvidence"][i]["receiptSha256"]=json!(digest(&e["receipts"][*k]));}}
 fn denied(&mut self,e:&Value){let head=self.b().durable_head();let report=self.b().engine().report().unwrap();assert!(self.put(e).is_err());assert_eq!(head,self.b().durable_head());assert_eq!(report,self.b().engine().report().unwrap());}
}
#[test]fn full_original_surplus_is_contributed_not_profit_and_replays_original_manifest(){let mut f=F::new(true);let before=f.b().engine().report().unwrap();let policy=f.b().engine().policy().clone();let manifest=fs::read(f.root.join("bank/manifest.json")).unwrap();let e=f.event("55579.915000",10);f.put(&e).unwrap();let after=f.b().engine().report().unwrap();for k in ["realized","newTradingRealized","inheritedRealizedGross","fees","ownedCost","positions","openingInventoryCost","reservedCash","fills","orders"]{assert_eq!(before[k],after[k],"{k}");}assert_eq!(f.b().engine().wallet.initial,95_579_915_000);assert_eq!(after["cash"],"70850.430000");assert_eq!(after["ownerCapitalAllocation"]["netContributions"],"55579.915000");let mut p=policy;p["maximumCommitted"]=json!("95579.915000");assert_eq!(f.b().engine().policy(),&p);assert_eq!(fs::read(f.root.join("bank/manifest.json")).unwrap(),manifest);assert!(!f.bank.as_mut().unwrap().accept("fixture",2,&e).unwrap());let head=f.b().durable_head();f.bank.take();f.bank=Some(Session::open_live(&f.root.join("bank"),&f.policy,&f.seed).unwrap());assert_eq!(head,f.b().durable_head());assert_eq!(after,f.b().engine().report().unwrap());}
#[test]fn remaining_seed_cash_not_official_mark_or_receipt_alone_bounds_contribution(){let mut f=F::new(false);let e=f.event("30850.430000",10);f.put(&e).unwrap();let e=f.event("0.000001",11);f.denied(&e);assert_eq!(f.b().engine().wallet.initial,70_850_430_000);}
#[test]fn partial_contribution_chain_cannot_repeat_id_or_exceed_approved_total(){let mut f=F::new(true);let e=f.event("10000.000000",10);let id=e["allocationId"].clone();f.put(&e).unwrap();let mut e=f.event("45579.915000",11);e["allocationId"]=id;f.denied(&e);let e=f.event("45579.915000",11);f.put(&e).unwrap();let e=f.event("0.000001",12);f.denied(&e);assert_eq!(f.b().engine().owner_capital_allocation_record().unwrap()["contributions"].as_array().unwrap().len(),2);}
#[test]fn original_closed_financial_history_and_unsubmitted_reserves_remain_identical(){let mut f=F::new(true);f.put(&json!({"type":"book","receivedAt":iso(2500),"book":{"exchangeId":"104","marketId":"104","tournamentId":T,"sequence":"1","sourceAt":iso(2500),"requestStartedAt":iso(2500),"receivedAt":iso(2500),"bids":[{"price":"0.400000","quantity":100}],"asks":[{"price":"0.450000","quantity":100}]}})).unwrap();let q=f.b().engine().order_records().into_iter().find(|q|q["side"]=="YES").unwrap();let qid=q["id"].as_u64().unwrap();f.put(&json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"a".repeat(64),"orderId":qid,"actualOrderId":"901","exchangeId":"104","marketId":"104","side":"YES","action":"buy","quantity":2,"price":"0.400000","receivedAt":iso(5500)})).unwrap();f.put(&json!({"type":"actual_fill","source":"official_sig_api_v1","receiptHash":"a".repeat(64),"orderId":qid,"actualOrderId":"901","exchangeId":"104","marketId":"104","side":"YES","action":"buy","fillId":"801","quantity":1,"price":"0.400000","fee":"0.010000","executedAt":iso(5600),"receivedAt":iso(5700)})).unwrap();f.put(&json!({"type":"actual_order_terminal","source":"official_sig_api_v1","receiptHash":"a".repeat(64),"orderId":qid,"actualOrderId":"901","exchangeId":"104","marketId":"104","side":"YES","action":"buy","filledQuantity":1,"fillsComplete":true,"status":"canceled","receivedAt":iso(5800)})).unwrap();let before=f.b().engine().report().unwrap();let orders=f.b().engine().order_records();let fills=f.b().engine().fills().to_vec();let e=f.event("55579.915000",6000);f.put(&e).unwrap();let after=f.b().engine().report().unwrap();for k in ["realized","fees","ownedCost","positions","reservedCash"]{assert_eq!(before[k],after[k],"{k}");}assert_eq!(orders,f.b().engine().order_records());assert_eq!(fills,f.b().engine().fills());assert_eq!(f.b().engine().live_order_bindings()[&qid],"901");}
#[test]fn malformed_proofs_cash_debt_positions_and_unknowns_cannot_raise_sizing(){for case in ["head","run","manifest","seed","report","policy","previous","initial","cap","over","unknown","active","open","coverage","cash","advance","debt","profile","position","missing","scope","receipt_hash","stale","overlap","endpoint"]{let mut f=F::new(true);let mut e=f.event("55579.915000",30_000);match case{"head"=>e["boundary"]["nativeHead"]["sequence"]=json!(99),"run"=>e["bankScope"]["runId"]=json!("other"),"manifest"=>e["bankScope"]["bankManifestHash"]=json!("b".repeat(64)),"seed"=>{e["receipts"]["account"]["data"]["balance"]=json!(99999);e["receipts"]["account"]["data"]["buyingPower"]=json!(99999)},"report"=>e["expectedReportHash"]=json!("b".repeat(64)),"policy"=>e["expectedPolicySha256"]=json!("b".repeat(64)),"previous"=>e["expectedPreviousAllocationSha256"]=json!("b".repeat(64)),"initial"=>e["expectedInitialCash"]=json!("1.000000"),"cap"=>e["effectiveMaximumCommitted"]=json!("100000.000000"),"over"=>e["delta"]=json!("55579.915001"),"unknown"=>e["boundary"]["unknownCount"]=json!(1),"active"=>e["boundary"]["activeRequest"]=json!("request"),"open"=>e["receipts"]["orders"]["data"]["data"]=json!([{"id":"1"}]),"coverage"=>e["receipts"]["orders"]["data"]["coverage"]["complete"]=json!(false),"cash"=>e["receipts"]["account"]["data"]["balance"]=json!(99999),"advance"=>e["receipts"]["collateral"]["data"]["availableAdvance"]=json!(1),"debt"=>e["receipts"]["collateral"]["data"]["data"][0]["outstandingAdvance"]=json!(1),"profile"=>e["receipts"]["account"]["data"]["id"]=json!("other"),"position"=>e["receipts"]["positions"]["data"]["positions"][0]["quantity"]=json!(1),"missing"=>{e["receipts"]["positions"]["data"]["positions"].as_array_mut().unwrap().pop();},"scope"=>e["scopeExchanges"]["101"]=json!("999"),"receipt_hash"=>e["originalSourceEvidence"][0]["receiptSha256"]=json!("f".repeat(64)),"stale"=>e["receipts"]["account"]["requestStartedAt"]=json!(iso(0)),"overlap"=>e["receipts"]["positions"]["requestStartedAt"]=e["receipts"]["account"]["requestStartedAt"].clone(),_=>e["receipts"]["account"]["endpoint"]=json!("/account")};if case!="receipt_hash"{F::resign(&mut e);}f.denied(&e);}}
#[test]fn paper_and_context_stripping_cannot_inherit_contributed_capital(){let mut f=F::new(true);let e=f.event("55579.915000",10);let mut paper=Engine::new(&f.policy).unwrap();assert!(paper.advance(&e).is_err());f.put(&e).unwrap();let report=f.b().engine().report().unwrap();assert_eq!(Engine::from_seed_state(&report).err(),Some("SEED_OWNER_CAPITAL_REQUIRE_REPLAY"));assert_eq!(moloch_replay::Wallet::restore_record(&report,95_579_915_000,0,0).err(),Some("SEED_OWNER_CAPITAL_REQUIRE_REPLAY"));let mut policy=f.b().engine().policy().clone();policy["maximumCommitted"]=json!("40000.000000");let mut engine=f.b().engine().clone();assert!(engine.update_policy(&policy).is_err());}
